import { createStore } from 'qortex-store';

const userStore = createStore({ 
  name: 'John', 
  loggedIn: false 
});

// Update via external set
userStore.set({ loggedIn: true });

const counterStore = createStore((set, get) => ({
  count: 0,
  // Use get() to read current state
  increment: () => set({ count: get().count + 1 }),
  // Use functional updates for atomic changes
  decrement: () => set((s) => ({ count: s.count - 1 })),
  // Access other state properties within actions
  resetIfHigh: () => {
    if (get().count > 10) set({ count: 0 });
  }
}));

const state = counterStore.get();
console.log(state.count); // 0

state.increment();
console.log(counterStore.get().count); // 1

const store = createStore({ a: 1, b: 2 });

// 1. Partial Merge (default)
store.set({ a: 10 }); // { a: 10, b: 2 }

// 2. Functional Update
store.set((s) => ({ a: s.a + 1 })); // { a: 11, b: 2 }

// 3. Full Replacement
store.set({ a: 0 }, true); // { a: 0 } (b is gone!)

const unsub = counterStore.subscribe((state, prevState) => {
  console.log('Changed:', prevState.count, '→', state.count);
});

// Stop listening
unsub();

import { createDB } from 'qortex-db';
import { createStorePersister } from 'qortex-db/store';
import { createStore } from 'qortex-store';

const db = createDB('myapp');
const persister = createStorePersister(db);

const store = createStore(
  { count: 0 },
  { persister }
);

// 1. On creation, store.get().count will be restored from DB
// 2. On change, it automatically debounces and writes to DB
